import React from 'react';
import { useParams, Link } from 'react-router-dom';

const StartReviewPage = () => {
  // The useParams hook lets us read the dynamic part of the URL (the employee's ID)
  const { employeeId } = useParams();

  return (
    <div className="flex flex-col h-full">
      <header className="bg-card-light dark:bg-card-dark p-4 border-b border-border-light dark:border-border-dark flex-shrink-0">
        <h1 className="text-2xl font-semibold text-text-light dark:text-text-dark">Start Performance Review</h1>
      </header>
      <div className="p-8">
        <h2 className="text-xl font-bold">Review for Employee ID: {employeeId}</h2>
        <p className="mt-2 text-subtext-light">This is where the performance review form will be built.</p>
        <Link to="/appraisal" className="text-primary hover:underline mt-6 inline-block">&larr; Back to Appraisals List</Link>
      </div>
    </div>
  );
};

export default StartReviewPage;
